<?php
declare(strict_types=1);require_once __DIR__.'/includes/auth.php';require_login();$pdo=lvj_files_db();$id=filter_var($_GET['id']??$_POST['id']??null,FILTER_VALIDATE_INT);if(!$id){http_response_code(404);exit('Estudio no válido.');}$message='';$error='';
if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();try{$title=trim((string)($_POST['titulo']??''));$decoded=json_decode((string)($_POST['contenido_json']??''),true,512,JSON_THROW_ON_ERROR);if(!is_array($decoded))throw new RuntimeException('JSON no válido.');$json=json_encode($decoded,JSON_UNESCAPED_UNICODE|JSON_UNESCAPED_SLASHES|JSON_THROW_ON_ERROR);$pdo->prepare('UPDATE lvj_bib_estudios_ia SET titulo=:title,contenido_json=:json,estado=\'revision\',revisado=0,updated_at=NOW() WHERE id=:id AND deleted_at IS NULL')->execute(['title'=>$title,'json'=>$json,'id'=>$id]);log_activity('editar','lvj_bib_estudios_ia',(int)$id,'Edición estructurada del contenido JSON');$message='Cambios guardados; el estudio volvió a revisión.';}catch(Throwable $e){$error='No se guardaron los cambios: '.$e->getMessage();}}
$studyStatement=$pdo->prepare('SELECT * FROM lvj_bib_estudios_ia WHERE id=:id AND deleted_at IS NULL');$studyStatement->execute(['id'=>$id]);$study=$studyStatement->fetch();if(!$study){http_response_code(404);exit('Estudio no encontrado.');}$pretty=json_encode(json_decode((string)$study['contenido_json'],true),JSON_PRETTY_PRINT|JSON_UNESCAPED_UNICODE|JSON_UNESCAPED_SLASHES);$pageTitle='Editar estudio bíblico';require __DIR__.'/includes/header.php';?>
<section class="page-heading"><div><span class="eyebrow">Biblia · <?php echo e((string)$study['referencia']);?></span><h1><?php echo e((string)($study['titulo']?:'Estudio sin título'));?></h1><p>El formulario valida JSON y nunca acepta HTML generado.</p></div></section><?php if($message):?><div class="alert success"><?php echo e($message);?></div><?php endif;?><?php if($error):?><div class="alert error"><?php echo e($error);?></div><?php endif;?>
<section class="panel-card"><form method="post"><?php echo csrf_field();?><input type="hidden" name="id" value="<?php echo (int)$id;?>"><label>Título<input name="titulo" maxlength="255" value="<?php echo e((string)$study['titulo']);?>"></label><label>Contenido JSON<textarea name="contenido_json" rows="32" spellcheck="false" style="font-family:monospace;width:100%;margin-top:8px"><?php echo e((string)$pretty);?></textarea></label><div class="form-actions"><button class="primary-button" type="submit">Guardar y enviar a revisión</button><a class="secondary-button" href="biblia-estudios-ia.php">Volver</a></div></form></section><?php require __DIR__.'/includes/footer.php';?>
